# Copy all HTML, MD, and JPG files to stage
Copy-Item -Path "$brain\*.html", "$brain\*.md", "$brain\*.jpg" -Destination $stage -Force

# Also create clean-named copies of the 8 renders in a sub-folder or root for easy family viewing
