}
foreach ($orig in $cleanNames.Keys) {
  Copy-Item -Path (Join-Path $brain $orig) -Destination (Join-Path $stage $cleanNames[$orig]) -Force
}

# Inject standalone browser CSS variable defaults into the exported HTML files so they work outside Antigravity
$standaloneStyle = @"
  <style>
    :root {
      --background: #f8fafc;
      --content: #f1f5f9;
      --card: #ffffff;
      --sidebar: #f1f5f9;
      --border: #cbd5e1;
      --foreground: #0f172a;
      --muted-foreground: #475569;
      --placeholder: #94a3b8;
      --primary: #059669;
      --primary-foreground: #ffffff;
      --secondary: #e2e8f0;
      --secondary-foreground: #0f172a;
      --accent: #0ea5e9;
    }
    @media (prefers-color-scheme: dark) {
      :root {
        --background: #0b1120;
        --content: #1e293b;
        --card: #0f172a;
        --sidebar: #0f172a;
        --border: #334155;
        --foreground: #f8fafc;
        --muted-foreground: #94a3b8;
        --placeholder: #64748b;
        --primary: #10b981;
        --primary-foreground: #ffffff;
        --secondary: #1e293b;
        --secondary-foreground: #f8fafc;
        --accent: #38bdf8;
      }
    }
"@

Get-ChildItem "$stage\*.html" | ForEach-Object {
  $content = [System.IO.File]::ReadAllText($_.FullName, [System.Text.Encoding]::UTF8)
  $content = $content.Replace("<style>", $standaloneStyle)
  [System.IO.File]::WriteAllText($_.FullName, $content, [System.Text.Encoding]::UTF8)
}

Write-Host "Prepared $((Get-ChildItem $stage).Count) files in stage directory."

