function renderRoomZoomSVG(svg, sp) {
  // Render the actual floor plan (PB or P1) and zoom the SVG viewBox directly onto the selected space!
  const prevView = currentView;
  currentView = sp.fl;
  renderMainSVG();
  currentView = prevView;

  const pad = 1.4; // 1.4 meters context padding around the room
  const vx = px(sp.x - pad);
  const vy = py(sp.y - pad);
  const vw = pw(sp.w + pad * 2);
  const vh = pw(sp.h + pad * 2);
  svg.setAttribute('viewBox', `${vx} ${vy} ${vw} ${vh}`);

  // Add N / S / E / W wall badges directly on the 4 walls of the zoomed room
  const rx = px(sp.x), ry = py(sp.y), rw = pw(sp.w), rh = pw(sp.h);
  svg.innerHTML += `
    <g>
      <rect x="${rx + rw/2 - 55}" y="${ry - 22}" width="110" height="18" rx="4" fill="#0284c7"/>
