$ErrorActionPreference = 'Stop'
$brainDir = 'C:\Users\noayaxel\.gemini\antigravity\brain\600d2fa3-f829-4025-9c03-3b55336e6869'
$stageDir = Join-Path $brainDir 'scratch\export_context'

if (Test-Path $stageDir) {
  Remove-Item -Path $stageDir -Recurse -Force
}
New-Item -ItemType Directory -Path $stageDir -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $stageDir '1_planos_y_visores_html') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $stageDir '2_renders_alta_resolucion\iteracion_1') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $stageDir '2_renders_alta_resolucion\iteracion_2') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $stageDir '2_renders_alta_resolucion\iteracion_3') -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $stageDir '3_conversacion_y_contexto\raw_logs') -Force | Out-Null

# 1. Actualizar galeria_interactiva_casa_completa_iter3.html para que use el render corregido del Despacho (iter3_estancia03_despacho_vista_sur_1794546084600.jpg)
$galScript = Join-Path $brainDir 'scratch\build_galeria_iter3.ps1'
if (Test-Path $galScript) {
  $galTxt = [System.IO.File]::ReadAllText($galScript, [System.Text.Encoding]::UTF8)
  $galTxt = $galTxt.Replace('iter3_05_despacho_vistas_patio_corrala_1794544397502.jpg', 'iter3_estancia03_despacho_vista_sur_1794546084600.jpg')
  [System.IO.File]::WriteAllText($galScript, $galTxt, [System.Text.Encoding]::UTF8)
  & powershell -NoProfile -ExecutionPolicy Bypass -File $galScript
}

# 2. Copiar todos los artefactos (.html, .md, .jpg) a la raíz de export_context y también clasificados en subcarpetas
$rootFiles = Get-ChildItem -Path $brainDir -File | Where-Object { $_.Extension -in @('.html', '.md', '.jpg', '.png') }

$cssFallback = @"
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    :root {
      --background: #f8fafc;
      --foreground: #0f172a;
      --card: #ffffff;
      --card-foreground: #0f172a;
      --content: #ffffff;
      --border: #e2e8f0;
      --muted: #f1f5f9;
      --muted-foreground: #64748b;
      --accent: #f1f5f9;
      --accent-foreground: #0f172a;
    }
  </style>
"@

foreach ($f in $rootFiles) {
  $destRoot = Join-Path $stageDir $f.Name
  if ($f.Extension -eq '.html') {
    $content = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
    if ($content -notmatch 'cdn\.tailwindcss\.com') {
      $content = $content.Replace('</head>', "$cssFallback`n</head>")
    }
    [System.IO.File]::WriteAllText($destRoot, $content, [System.Text.Encoding]::UTF8)
    [System.IO.File]::WriteAllText((Join-Path $stageDir "1_planos_y_visores_html\$($f.Name)"), $content, [System.Text.Encoding]::UTF8)
  } elseif ($f.Extension -eq '.md') {
    $content = [System.IO.File]::ReadAllText($f.FullName, [System.Text.Encoding]::UTF8)
    # Reemplazar rutas absolutas por relativas para que funcionen en cualquier ordenador
    $contentRel = $content.Replace('C:/Users/noayaxel/.gemini/antigravity/brain/600d2fa3-f829-4025-9c03-3b55336e6869/', './')
    [System.IO.File]::WriteAllText($destRoot, $contentRel, [System.Text.Encoding]::UTF8)
    [System.IO.File]::WriteAllText((Join-Path $stageDir "1_planos_y_visores_html\$($f.Name)"), $contentRel, [System.Text.Encoding]::UTF8)
  } else {
    Copy-Item -Path $f.FullName -Destination $destRoot -Force
    if ($f.Name -like 'render_*') {
      Copy-Item -Path $f.FullName -Destination (Join-Path $stageDir "2_renders_alta_resolucion\iteracion_1\$($f.Name)") -Force
    } elseif ($f.Name -like 'iter2_*') {
      Copy-Item -Path $f.FullName -Destination (Join-Path $stageDir "2_renders_alta_resolucion\iteracion_2\$($f.Name)") -Force
    } elseif ($f.Name -like 'iter3_*') {
      Copy-Item -Path $f.FullName -Destination (Join-Path $stageDir "2_renders_alta_resolucion\iteracion_3\$($f.Name)") -Force
    }
  }
}

# 3. Exportar los logs de conversación (.jsonl) y generar transcripción legible en Markdown y HTML
$logDir = Join-Path $brainDir '.system_generated\logs'
if (Test-Path $logDir) {
  Copy-Item -Path (Join-Path $logDir '*') -Destination (Join-Path $stageDir '3_conversacion_y_contexto\raw_logs') -Force -ErrorAction SilentlyContinue
}

$fullLog = Join-Path $logDir 'transcript_full.jsonl'
if (-not (Test-Path $fullLog)) {
  $fullLog = Join-Path $logDir 'transcript.jsonl'
}

$mdLines = New-Object System.Collections.Generic.List[string]
$mdLines.Add('# Transcripción Completa de la Conversación — Proyecto Vivienda Unifamiliar en Oleiros')
$mdLines.Add('')
$mdLines.Add('- **ID de Conversación:** `600d2fa3-f829-4025-9c03-3b55336e6869`')
$mdLines.Add("- **Fecha de Exportación:** $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')")
$mdLines.Add('')
$mdLines.Add('---')
$mdLines.Add('')

if (Test-Path $fullLog) {
  $lines = [System.IO.File]::ReadAllLines($fullLog, [System.Text.Encoding]::UTF8)
  foreach ($line in $lines) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    try {
      $obj = $line | ConvertFrom-Json
      $stepIdx = $obj.step_index
      $type = $obj.type
      $ts = $obj.created_at
      $content = $obj.content
      if ($type -eq 'USER_INPUT' -and -not [string]::IsNullOrWhiteSpace($content)) {
        $mdLines.Add("## 👤 Usuario (Paso $stepIdx — $ts)")
        $mdLines.Add('')
        $mdLines.Add($content)
        $mdLines.Add('')
        $mdLines.Add('---')
        $mdLines.Add('')
      } elseif ($type -eq 'PLANNER_RESPONSE' -and -not [string]::IsNullOrWhiteSpace($content)) {
        $mdLines.Add("## 🏛️ Arquitecto Antigravity (Paso $stepIdx — $ts)")
        $mdLines.Add('')
        $mdLines.Add($content)
        $mdLines.Add('')
        $mdLines.Add('---')
        $mdLines.Add('')
      }
    } catch {}
  }
}

$convMdPath = Join-Path $stageDir '3_conversacion_y_contexto\CONVERSACION_COMPLETA_LEGIBLE.md'
[System.IO.File]::WriteAllLines($convMdPath, $mdLines, [System.Text.Encoding]::UTF8)
Copy-Item -Path $convMdPath -Destination (Join-Path $stageDir 'CONVERSACION_COMPLETA_LEGIBLE.md') -Force

Write-Host "Prepared context package at $stageDir with $((Get-ChildItem -Path $stageDir -Recurse -File).Count) total files."
